import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.Wk4ah3nE.js";const k=JSON.parse(`{"title":"Troubleshooting","description":"Diagnose the common failure modes of Proxmox VM Autoscale — service won't start, SSH failures, VMs that never scale, usage stuck at zero, and changes that don't reach the guest.","frontmatter":{"title":"Troubleshooting","description":"Diagnose the common failure modes of Proxmox VM Autoscale — service won't start, SSH failures, VMs that never scale, usage stuck at zero, and changes that don't reach the guest.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/troubleshooting.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/troubleshooting.html"}],["meta",{"property":"og:title","content":"Troubleshooting"}],["meta",{"property":"og:description","content":"Diagnose the common failure modes of Proxmox VM Autoscale — service won't start, SSH failures, VMs that never scale, usage stuck at zero, and changes that don't reach the guest."}]]},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":null}`),n={name:"guide/troubleshooting.md"};function o(l,s,h,p,r,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start here, in order: is the service running, is it connecting, is it reading usage, is it deciding to scale, does the change reach the guest.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -50</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/vm_autoscale.log</span></span></code></pre></div><h2 id="the-service-will-not-start" tabindex="-1">The service will not start <a class="header-anchor" href="#the-service-will-not-start" aria-label="Permalink to &quot;The service will not start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> critical</span></span></code></pre></div><h3 id="missing-required-configuration-sections" tabindex="-1"><code>Missing required configuration sections: ...</code> <a class="header-anchor" href="#missing-required-configuration-sections" aria-label="Permalink to &quot;\`Missing required configuration sections: ...\`&quot;">​</a></h3><p>One of <code>scaling_thresholds</code>, <code>scaling_limits</code>, <code>proxmox_hosts</code>, <code>virtual_machines</code> is absent. All four are mandatory even if you are not using them meaningfully.</p><h3 id="configuration-file-not-found-at-usr-local-bin-vm-autoscale-config-yaml" tabindex="-1"><code>Configuration file not found at /usr/local/bin/vm_autoscale/config.yaml</code> <a class="header-anchor" href="#configuration-file-not-found-at-usr-local-bin-vm-autoscale-config-yaml" aria-label="Permalink to &quot;\`Configuration file not found at /usr/local/bin/vm_autoscale/config.yaml\`&quot;">​</a></h3><p>The path is hardcoded. If you installed elsewhere, either symlink it or edit <code>main()</code> in <code>autoscale.py</code>.</p><h3 id="gotify-is-enabled-but-configuration-is-incomplete" tabindex="-1"><code>Gotify is enabled but configuration is incomplete</code> <a class="header-anchor" href="#gotify-is-enabled-but-configuration-is-incomplete" aria-label="Permalink to &quot;\`Gotify is enabled but configuration is incomplete\`&quot;">​</a></h3><p><code>gotify.enabled: true</code> with <code>server_url</code> or <code>app_token</code> missing. Same shape of error for email:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Email alerts are enabled but missing configuration: smtp_server, smtp_user</span></span></code></pre></div><h3 id="yaml-syntax-errors" tabindex="-1">YAML syntax errors <a class="header-anchor" href="#yaml-syntax-errors" aria-label="Permalink to &quot;YAML syntax errors&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import yaml; yaml.safe_load(open(&#39;/usr/local/bin/vm_autoscale/config.yaml&#39;))&quot;</span></span></code></pre></div><p>Tabs are the usual culprit — YAML forbids them for indentation.</p><h3 id="permission-denied-writing-the-log" tabindex="-1">Permission denied writing the log <a class="header-anchor" href="#permission-denied-writing-the-log" aria-label="Permalink to &quot;Permission denied writing the log&quot;">​</a></h3><p>The service needs write access to <code>logging_config.json</code>&#39;s <code>filename</code> (default <code>/var/log/vm_autoscale.log</code>). Running as root this is fine; if you changed <code>User=</code>, it is probably not.</p><h2 id="ssh-failures" tabindex="-1">SSH failures <a class="header-anchor" href="#ssh-failures" aria-label="Permalink to &quot;SSH failures&quot;">​</a></h2><h3 id="authentication-failed-for-192-168-1-10" tabindex="-1"><code>Authentication failed for 192.168.1.10</code> <a class="header-anchor" href="#authentication-failed-for-192-168-1-10" aria-label="Permalink to &quot;\`Authentication failed for 192.168.1.10\`&quot;">​</a></h3><p>Not retried — credentials are wrong, or the key was rejected. Test the exact same path by hand:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/.ssh/id_rsa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@192.168.1.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;qm list&#39;</span></span></code></pre></div><h3 id="key-authentication-fails-but-the-key-is-fine" tabindex="-1">Key authentication fails but the key is fine <a class="header-anchor" href="#key-authentication-fails-but-the-key-is-fine" aria-label="Permalink to &quot;Key authentication fails but the key is fine&quot;">​</a></h3><p><strong>Only RSA keys are supported.</strong> The key file is loaded specifically as an RSA key, so an Ed25519 or ECDSA key fails to load however valid it is. This is the single most common cause of &quot;my key works from the shell but not from the service&quot;.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/.ssh/id_ed25519</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # OPENSSH PRIVATE KEY → will not work</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/.ssh/vm_autoscale_rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/.ssh/vm_autoscale_rsa.pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@192.168.1.10</span></span></code></pre></div><p>Then point <code>ssh_key</code> at the new private key. See <a href="/proxmox-vm-autoscale/reference/limitations.html#only-rsa-ssh-keys-are-supported">known limitations</a>.</p><h3 id="failed-to-connect-to-192-168-1-10-after-5-attempts" tabindex="-1"><code>Failed to connect to 192.168.1.10 after 5 attempts</code> <a class="header-anchor" href="#failed-to-connect-to-192-168-1-10-after-5-attempts" aria-label="Permalink to &quot;\`Failed to connect to 192.168.1.10 after 5 attempts\`&quot;">​</a></h3><p>Five attempts with exponential backoff (1, 2, 4, 8, 16 s) — roughly 31 seconds before giving up. Network, firewall, or <code>sshd</code> not listening on <code>ssh_port</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span></code></pre></div><h3 id="both-password-and-key-configured" tabindex="-1">Both password and key configured <a class="header-anchor" href="#both-password-and-key-configured" aria-label="Permalink to &quot;Both password and key configured&quot;">​</a></h3><p>If <code>ssh_password</code> is set it wins; <code>ssh_key</code> is ignored entirely. Remove or blank the password to force key auth. The shipped example config has <strong>both</strong> filled in with placeholders, so leaving it half-edited means the placeholder password is what gets used.</p><h3 id="too-many-ssh-sessions" tabindex="-1">Too many SSH sessions <a class="header-anchor" href="#too-many-ssh-sessions" aria-label="Permalink to &quot;Too many SSH sessions&quot;">​</a></h3><p>A connection is opened and closed per VM per cycle. With many VMs and a short <code>check_interval</code>, you can hit <code>MaxStartups</code> or <code>MaxSessions</code> on the node. Raise <code>check_interval</code>, or raise the limits in <code>/etc/ssh/sshd_config</code>.</p><h2 id="a-vm-never-scales" tabindex="-1">A VM never scales <a class="header-anchor" href="#a-vm-never-scales" aria-label="Permalink to &quot;A VM never scales&quot;">​</a></h2><p>Work down this list:</p><p><strong>1. Is it enabled?</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scaling_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cpu_scaling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ram_scaling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p><strong>2. Does <code>proxmox_host</code> match a host <code>name</code> exactly?</strong> A mismatch means the VM entry is never reached — and there is no warning for it. Case and whitespace matter.</p><p><strong>3. Is the guest running?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] VM 101 is not running. Skipping scaling.</span></span></code></pre></div><p><strong>4. Is the host blocking it?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] Host pve1 resources maxed out. Skipping scaling.</span></span></code></pre></div><p>Raise <code>host_limits</code>, or accept that the node is genuinely full. On ZFS hosts, ARC counts as used memory — check <code>arc_summary</code> before concluding the ceiling is real.</p><p><strong>5. Is usage actually crossing a threshold?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] VM 101 current usage - CPU: 45.2%, RAM: 62.1%</span></span></code></pre></div><p>45% is inside a 20–80 dead band. Nothing is wrong.</p><p><strong>6. Is it already at a limit?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] No CPU scaling required.</span></span></code></pre></div><p>Check <code>qm config 101</code> against your <code>scaling_limits</code>.</p><p><strong>7. Is it in cooldown?</strong> No log line is emitted for this. Look at the timestamp of the last <code>Scaled ...</code> line for that VM and compare against <code>scale_cooldown</code>.</p><h2 id="usage-always-reads-0" tabindex="-1">Usage always reads 0% <a class="header-anchor" href="#usage-always-reads-0" aria-label="Permalink to &quot;Usage always reads 0%&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] CPU usage not found in output.</span></span>
<span class="line"><span>[WARNING] RAM memory values not found in output.</span></span></code></pre></div><p>Usage is scraped from <code>pvesh</code>&#39;s human-readable table, and the format is version-sensitive. Run the exact command on the node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cluster/resources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;qemu/101&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;│&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $6, $15, $16}&#39;</span></span></code></pre></div><p>You want something like <code>3.17% 5.00 GiB 3.82 GiB</code>. Empty output or wrong columns means the format on your Proxmox version does not match what the parser expects.</p><div class="danger custom-block"><p class="custom-block-title">This failure mode scales VMs down</p><p><code>0.0</code> is below every reasonable <code>low</code> threshold, so a parse failure reads as &quot;completely idle&quot; and every affected VM walks down to its minimum, one step per cycle. If you see these warnings, stop the service before it finishes.</p></div><p>Also check the <code>grep</code> is not matching the wrong guest — <code>grep &#39;qemu/101&#39;</code> matches <code>qemu/1010</code> too. If you have both, the parse silently reads the wrong row.</p><h2 id="the-change-does-not-reach-the-guest" tabindex="-1">The change does not reach the guest <a class="header-anchor" href="#the-change-does-not-reach-the-guest" aria-label="Permalink to &quot;The change does not reach the guest&quot;">​</a></h2><h3 id="ram-changes-but-the-guest-does-not-see-it" tabindex="-1">RAM changes but the guest does not see it <a class="header-anchor" href="#ram-changes-but-the-guest-does-not-see-it" aria-label="Permalink to &quot;RAM changes but the guest does not see it&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] VM 101 has memory hotplug enabled but NUMA is disabled.</span></span>
<span class="line"><span>          Memory changes will require a reboot.</span></span></code></pre></div><p>Enable NUMA and <strong>reboot the guest</strong> — NUMA is a topology change and does not apply live.</p><p>If both are enabled and it still does not take effect, the balloon driver is missing or wedged inside the guest:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inside the guest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsmod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtio_balloon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dmesg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> balloon</span></span></code></pre></div><h3 id="cpu-count-does-not-change-inside-the-guest" tabindex="-1">CPU count does not change inside the guest <a class="header-anchor" href="#cpu-count-does-not-change-inside-the-guest" aria-label="Permalink to &quot;CPU count does not change inside the guest&quot;">​</a></h3><p>Scaling <code>cores</code> requires a reboot; only <code>vcpus</code> is live. Look at which one the log said it changed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] VM 101: Increased cores to 5 (requires reboot for full effect)</span></span>
<span class="line"><span>          and vCPUs to 5 (hotplug applied).</span></span></code></pre></div><p>Removing a vCPU is also unreliable — Windows guests in particular often refuse. QEMU accepts the command and the service reports success either way.</p><h3 id="qm-set-fails-but-the-log-says-it-succeeded" tabindex="-1"><code>qm set</code> fails but the log says it succeeded <a class="header-anchor" href="#qm-set-fails-but-the-log-says-it-succeeded" aria-label="Permalink to &quot;\`qm set\` fails but the log says it succeeded&quot;">​</a></h3><p>Command results are not checked for a non-zero exit status before the success line is written. Confirm on the node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 101</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cores|vcpus|memory|balloon&#39;</span></span></code></pre></div><h2 id="it-scales-up-and-down-constantly" tabindex="-1">It scales up and down constantly <a class="header-anchor" href="#it-scales-up-and-down-constantly" aria-label="Permalink to &quot;It scales up and down constantly&quot;">​</a></h2><p>The dead band between <code>low</code> and <code>high</code> is too narrow for how the workload actually moves.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scaling_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    high</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">85</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    low</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # a wide band absorbs normal variation</span></span></code></pre></div><p>Also raise <code>scale_cooldown</code>. Remember the effective interval is <code>max(check_interval, scale_cooldown)</code>, so a cooldown below the poll interval does nothing.</p><p>Repeated <code>systemctl restart</code> also defeats the cooldown, since the timers are in memory.</p><h2 id="notifications-do-not-arrive" tabindex="-1">Notifications do not arrive <a class="header-anchor" href="#notifications-do-not-arrive" aria-label="Permalink to &quot;Notifications do not arrive&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notification</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/vm_autoscale.log</span></span></code></pre></div><p><code>Failed to send notification through any channel</code> includes the original message and the per-channel errors. Test Gotify independently:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://gotify.example.com/message&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_TOKEN&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;title=test&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;message=test&quot;</span></span></code></pre></div><p>For SMTP, remember <code>starttls()</code> is always called — a relay that does not advertise STARTTLS will fail. Leave <code>smtp_password</code> empty to skip authentication on an IP-authenticated relay.</p><p>Also: notifications only fire on <strong>actual changes</strong>. A threshold crossed while at a limit or in cooldown sends nothing, by design.</p><h2 id="billing-produces-no-csv" tabindex="-1">Billing produces no CSV <a class="header-anchor" href="#billing-produces-no-csv" aria-label="Permalink to &quot;Billing produces no CSV&quot;">​</a></h2><p>Expected. Report generation is not wired into the service — only spec recording is. See <a href="/proxmox-vm-autoscale/guide/billing.html#what-is-automatic-and-what-is-not">billing</a> for the script that generates one.</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Before opening an issue, collect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pveversion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Then <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a> with your config <strong>with every credential removed</strong> — <code>ssh_password</code>, <code>smtp_password</code>, <code>app_token</code>, host addresses if they are sensitive.</p>`,86)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
